<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: #0f172a;
    color: #e2e8f0;
    min-height: 100vh;
    padding: 32px;
  }
  h1 {
    text-align: center;
    margin-bottom: 24px;
    font-weight: 700;
    letter-spacing: -0.5px;
    color: #f8fafc;
  }
  .add-bar {
    max-width: 1100px;
    margin: 0 auto 28px;
    display: flex;
    gap: 10px;
  }
  #new-card {
    flex: 1;
    padding: 12px 16px;
    border-radius: 10px;
    border: 1px solid #334155;
    background: #1e293b;
    color: #f8fafc;
    font-size: 15px;
    outline: none;
  }
  #new-card:focus { border-color: #6366f1; box-shadow: 0 0 0 3px rgba(99,102,241,0.25); }
  #add-card {
    padding: 12px 22px;
    border: none;
    border-radius: 10px;
    background: #6366f1;
    color: #fff;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s ease;
  }
  #add-card:hover { background: #4f46e5; }
  #add-card:active { background: #4338ca; }

  .board {
    max-width: 1100px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
    align-items: start;
  }
  .column {
    background: #1e293b;
    border-radius: 14px;
    padding: 16px;
    min-height: 140px;
    display: flex;
    flex-direction: column;
    transition: box-shadow 0.15s ease;
  }
  .column.drag-over { box-shadow: inset 0 0 0 2px #6366f1; }
  .col-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
    padding-bottom: 12px;
    border-bottom: 1px solid #334155;
  }
  .col-header h2 { font-size: 16px; font-weight: 600; color: #f8fafc; }
  .count {
    background: #334155;
    color: #cbd5e1;
    font-size: 13px;
    font-weight: 600;
    min-width: 24px;
    height: 24px;
    padding: 0 8px;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }
  .card-container {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-height: 40px;
  }
  .card {
    background: #f8fafc;
    color: #0f172a;
    border-radius: 10px;
    padding: 12px 14px;
    box-shadow: 0 1px 2px rgba(0,0,0,0.3);
    cursor: grab;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    transition: transform 0.1s ease, box-shadow 0.1s ease, opacity 0.1s ease;
  }
  .card:hover { transform: translateY(-2px); box-shadow: 0 4px 10px rgba(0,0,0,0.4); }
  .card.dragging { opacity: 0.45; cursor: grabbing; }
  .card-title { font-size: 14px; line-height: 1.35; word-break: break-word; flex: 1; }
  .card-del {
    border: none;
    background: transparent;
    color: #94a3b8;
    font-size: 20px;
    line-height: 1;
    cursor: pointer;
    padding: 2px 6px;
    border-radius: 6px;
    transition: color 0.15s ease, background 0.15s ease;
  }
  .card-del:hover { color: #ef4444; background: #fee2e2; }

  @media (max-width: 720px) {
    .board { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>
  <h1>Kanban Board</h1>
  <div class="add-bar">
    <input type="text" id="new-card" placeholder="What needs to be done?" />
    <button id="add-card">Add Card</button>
  </div>
  <div class="board">
    <section class="column" id="col-todo">
      <div class="col-header">
        <h2>To Do</h2>
        <span class="count">0</span>
      </div>
      <div class="card-container"></div>
    </section>
    <section class="column" id="col-doing">
      <div class="col-header">
        <h2>In Progress</h2>
        <span class="count">0</span>
      </div>
      <div class="card-container"></div>
    </section>
    <section class="column" id="col-done">
      <div class="col-header">
        <h2>Done</h2>
        <span class="count">0</span>
      </div>
      <div class="card-container"></div>
    </section>
  </div>

<script>
(function () {
  const STORAGE_KEY = 'kanban-board-state';
  const COLUMNS = ['todo', 'doing', 'done'];

  function loadState() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) return JSON.parse(raw);
    } catch (e) {}
    return [];
  }

  let cards = loadState();

  function saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(cards));
    } catch (e) {}
  }

  function containerFor(colId) {
    return document.querySelector('#' + colId + ' .card-container');
  }
  function countElFor(colId) {
    return document.querySelector('#' + colId + ' .count');
  }

  function makeCardEl(card) {
    const el = document.createElement('div');
    el.className = 'card';
    el.draggable = true;
    el.dataset.id = card.id;

    const title = document.createElement('span');
    title.className = 'card-title';
    title.textContent = card.title;

    const del = document.createElement('button');
    del.className = 'card-del';
    del.innerHTML = '&times;';
    del.setAttribute('aria-label', 'Delete card: ' + card.title);

    del.addEventListener('click', function (e) {
      e.stopPropagation();
      cards = cards.filter(function (c) { return c.id !== card.id; });
      saveState();
      render();
    });

    el.addEventListener('dragstart', function (e) {
      el.classList.add('dragging');
      e.dataTransfer.setData('text/plain', card.id);
      e.dataTransfer.effectAllowed = 'move';
    });
    el.addEventListener('dragend', function () {
      el.classList.remove('dragging');
    });

    el.appendChild(title);
    el.appendChild(del);
    return el;
  }

  function render() {
    COLUMNS.forEach(function (colId) {
      containerFor(colId).innerHTML = '';
    });
    cards.forEach(function (card) {
      const c = containerFor('col-' + card.col);
      if (c) c.appendChild(makeCardEl(card));
    });
    COLUMNS.forEach(function (colId) {
      const n = cards.filter(function (c) { return c.col === colId; }).length;
      countElFor('col-' + colId).textContent = String(n);
    });
  }

  function setupDropTargets() {
    COLUMNS.forEach(function (colId) {
      const col = document.getElementById('col-' + colId);

      col.addEventListener('dragover', function (e) {
        e.preventDefault();
        col.classList.add('drag-over');
      });

      col.addEventListener('dragleave', function (e) {
        if (!col.contains(e.relatedTarget)) {
          col.classList.remove('drag-over');
        }
      });

      col.addEventListener('drop', function (e) {
        e.preventDefault();
        col.classList.remove('drag-over');
        const id = e.dataTransfer.getData('text/plain');
        if (!id) return;
        const card = cards.find(function (c) { return c.id === id; });
        if (card && card.col !== colId) {
          card.col = colId;
          saveState();
          render();
        } else if (card) {
          render();
        }
      });
    });
  }

  function addCard() {
    const input = document.getElementById('new-card');
    const text = input.value.trim();
    if (!text) return;
    cards.push({
      id: 'c' + Date.now() + Math.random().toString(36).slice(2),
      title: text,
      col: 'todo'
    });
    input.value = '';
    saveState();
    render();
  }

  document.getElementById('add-card').addEventListener('click', addCard);
  document.getElementById('new-card').addEventListener('keydown', function (e) {
    if (e.key === 'Enter') addCard();
  });

  setupDropTargets();
  render();
})();
</script>
</body>
</html>
